using Servicio.RetazoMarket.Business.DTOs.ProveedorMaterial;using Servicio.RetazoMarket.Business.Exceptions;using Servicio.RetazoMarket.Business.Interfaces;using Servicio.RetazoMarket.Business.Mappers;using Servicio.RetazoMarket.Business.Validators;using Servicio.RetazoMarket.DataManagment.Interfaces;
namespace Servicio.RetazoMarket.Business.Services;
public class ProveedorMaterialService:IProveedorMaterialService { private readonly IProveedorMaterialDataService _data;private readonly IProveedorDataService _proveedores;private readonly IMaterialDataService _materiales;public ProveedorMaterialService(IProveedorMaterialDataService data,IProveedorDataService proveedores,IMaterialDataService materiales)=>(_data,_proveedores,_materiales)=(data,proveedores,materiales);public async Task<ProveedorMaterialResponse?> ObtenerAsync(int m,int p,CancellationToken ct=default){var x=await _data.ObtenerAsync(m,p,ct);return x is null?null:ProveedorMaterialBusinessMapper.ToResponse(x);}public async Task<IReadOnlyList<ProveedorMaterialResponse>> ObtenerPorProveedorAsync(int id,CancellationToken ct=default)=>(await _data.ObtenerPorProveedorAsync(id,ct)).Select(ProveedorMaterialBusinessMapper.ToResponse).ToList();public async Task<IReadOnlyList<ProveedorMaterialResponse>> ObtenerPorMaterialAsync(int id,CancellationToken ct=default)=>(await _data.ObtenerPorMaterialAsync(id,ct)).Select(ProveedorMaterialBusinessMapper.ToResponse).ToList();public async Task<ProveedorMaterialResponse> CrearAsync(CrearProveedorMaterialRequest r,CancellationToken ct=default){var e=ProveedorMaterialValidator.Validar(r);if(e.Any())throw new ValidationException("Solicitud inválida.",e);await Activos(r.id_material,r.id_proveedor,ct);if(await _data.ExisteAsync(r.id_material,r.id_proveedor,ct))throw new ValidationException("La relación entre proveedor y material ya existe.");return ProveedorMaterialBusinessMapper.ToResponse(await _data.CrearAsync(ProveedorMaterialBusinessMapper.ToDataModel(r),ct));}public async Task<ProveedorMaterialResponse?> ActualizarAsync(ActualizarProveedorMaterialRequest r,CancellationToken ct=default){var e=ProveedorMaterialValidator.Validar(r);if(e.Any())throw new ValidationException("Solicitud inválida.",e);await Activos(r.id_material,r.id_proveedor,ct);var m=await _data.ActualizarAsync(ProveedorMaterialBusinessMapper.ToDataModel(r),ct);return m is null?null:ProveedorMaterialBusinessMapper.ToResponse(m);}private async Task Activos(int m,int p,CancellationToken ct){var material=await _materiales.ObtenerPorIdAsync(m,ct);if(material is null||material.mat_estado!="ACT")throw new ValidationException("El material no existe o está inactivo.");var proveedor=await _proveedores.ObtenerPorIdAsync(p,ct);if(proveedor is null||proveedor.prov_estado!="ACT")throw new ValidationException("El proveedor no existe o está inactivo.");}}
